     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.ObjectMapper;
     5	import jakarta.persistence.AttributeConverter;
     6	import jakarta.persistence.Converter;
     7	import java.math.BigDecimal;
     8	import java.util.LinkedHashMap;
     9	import java.util.Map;
    10	
    11	@Converter(autoApply = true)
    12	public class OrderSummaryConverter implements AttributeConverter<OrderSummary, String> {
    13	
    14	    private static final ObjectMapper mapper = new ObjectMapper();
    15	
    16	    @Override
    17	    public String convertToDatabaseColumn(OrderSummary attribute) {
    18	        if (attribute == null) {
    19	            return null;
    20	        }
    21	        try {
    22	            Map<String, Object> map = new LinkedHashMap<>();
    23	            map.put("productsSubtotal", attribute.getProductsSubtotal());
    24	            map.put("couponDiscount", attribute.getCouponDiscount());
    25	            map.put("shippingCost", attribute.getShippingCost());
    26	            map.put("deliveryDays", attribute.getDeliveryDays());
    27	            map.put("insurance", attribute.getInsurance());
    28	            map.put("paymentAdjustment", attribute.getPaymentAdjustment());
    29	            map.put("finalTotal", attribute.getFinalTotal());
    30	            map.put("installments", attribute.getInstallments());
    31	            map.put("installmentAmount", attribute.getInstallmentAmount());
    32	            map.put("nextPurchaseCredit", attribute.getNextPurchaseCredit());
    33	            map.put("gift", attribute.getGift());
    34	            return mapper.writeValueAsString(map);
    35	        } catch (JsonProcessingException e) {
    36	            throw new RuntimeException(e);
    37	        }
    38	    }
    39	
    40	    @Override
    41	    public OrderSummary convertToEntityAttribute(String dbData) {
    42	        if (dbData == null) {
    43	            return null;
    44	        }
    45	        try {
    46	            @SuppressWarnings("unchecked")
    47	            Map<String, Object> map = mapper.readValue(dbData, Map.class);
    48	            return new OrderSummary(
    49	                    new BigDecimal(map.get("productsSubtotal").toString()),
    50	                    new BigDecimal(map.get("couponDiscount").toString()),
    51	                    new BigDecimal(map.get("shippingCost").toString()),
    52	                    ((Number) map.get("deliveryDays")).intValue(),
    53	                    new BigDecimal(map.get("insurance").toString()),
    54	                    new BigDecimal(map.get("paymentAdjustment").toString()),
    55	                    new BigDecimal(map.get("finalTotal").toString()),
    56	                    ((Number) map.get("installments")).intValue(),
    57	                    new BigDecimal(map.get("installmentAmount").toString()),
    58	                    new BigDecimal(map.get("nextPurchaseCredit").toString()),
    59	                    (Boolean) map.get("gift")
    60	            );
    61	        } catch (JsonProcessingException e) {
    62	            throw new RuntimeException(e);
    63	        }
    64	    }
    65	}
